fn competitive_owned_cli_refuses_cell_and_prompt_identity_drift_before_http_or_outputs() {
    for drift in ["cell", "prompt", "provenance"] {
        let root = tempfile::tempdir().unwrap();
        let server = Server::new(GOOD);
        let path = input(root.path(), &server.base);
        if drift == "cell" {
            let mut doc: Value = serde_json::from_slice(&std::fs::read(&path).unwrap()).unwrap();
            doc["cell"]["concurrency"] = json!(3);
            std::fs::write(&path, serde_json::to_vec(&doc).unwrap()).unwrap();
        } else if drift == "prompt" {
            std::fs::write(root.path().join("manifest.json"), "changed").unwrap();
        } else {
            let mut manifest: Value =
                serde_json::from_slice(&std::fs::read(root.path().join("manifest.json")).unwrap())
                    .unwrap();
            manifest["metadata"]["rows"][0]["session_id"] = json!("wrong");
            let bytes = serde_json::to_vec(&manifest).unwrap();
            std::fs::write(root.path().join("manifest.json"), &bytes).unwrap();
            let mut config: Value =
                serde_json::from_slice(&std::fs::read(root.path().join("config.json")).unwrap())
                    .unwrap();
            config["thoughtworks"]["selection"]["manifest_sha256"] =
                json!(hex::encode(Sha256::digest(&bytes)));
            let bytes = serde_json::to_vec(&config).unwrap();
            std::fs::write(root.path().join("config.json"), &bytes).unwrap();
            let mut doc: Value = serde_json::from_slice(&std::fs::read(&path).unwrap()).unwrap();
            doc["config_sha256"] = json!(hex::encode(Sha256::digest(&bytes)));
            std::fs::write(&path, serde_json::to_vec(&doc).unwrap()).unwrap();
        }

        assert!(!run(root.path(), &path));
        let requests = server.close();
        assert!(requests.is_empty());
        assert!(!root.path().join("output").exists());
        root.close().unwrap();
    }
}

fn competitive_mesh_raw_and_adaptive_commands_share_exact_fixed_lane_ceiling() {
    let root = tempfile::tempdir().unwrap();
    let (mut model, mut backend, artifact) = optional_fixture(root.path());
    model["key"] = json!("fixture");
    model["model_id"] = json!("fixture-model");
    model["layer_end"] = json!(40);
    model["cache_payload"] = json!("kv-recurrent");
    let runtime = root.path().join("runtime");
    std::fs::create_dir(&runtime).unwrap();
    std::fs::write(runtime.join("fixture"), b"inert").unwrap();
    backend.runtime = Some(Artifact {
        path: runtime.clone(),
        sha256: crate::product::digest::tree_sha256(&runtime)
            .unwrap_or_else(|f| panic!("{}", f.error)),
    });
    let mut commands = std::collections::BTreeMap::new();
    for arm in ["mesh", "mesh-adaptive", "llama"] {
        let cell = json!({"arm":arm,"output_tokens":8});
        let selection = Selection {
            model: &model,
            cell: &cell,
            backend: &backend,
            artifact: &artifact,
            port: 1234,
            directory: root.path(),
            capacity: Capacity {
                context: 16384,
                lanes: 4,
            },
            cache: true,
        };
        let command = if arm == "llama" {
            external(&selection, arm, "fixture-model", &mut json!({})).unwrap()
        } else {
            mesh(&selection, &mut json!({})).unwrap()
        };
        commands.insert(arm, command);
    }
    for arm in ["mesh", "mesh-adaptive"] {
        let args = &commands[arm];
        for (flag, value) in [
            ("--generation-concurrency", "4"),
            ("--generation-queue-capacity", "256"),
            ("--generation-admission-timeout-secs", "600"),
        ] {
            assert!(args.windows(2).any(|p| p == [flag, value]));
        }
    }
    assert!(
        commands["llama"]
            .windows(2)
            .any(|p| p == ["--parallel", "4"])
    );
    assert!(commands["llama"].iter().any(|v| v == "--kv-unified"));
    assert!(!commands["llama"].iter().any(|v| v == "--no-cache-prompt"));
    assert!(
        commands["mesh-adaptive"]
            .iter()
            .any(|v| v == "--adaptive-generation-concurrency")
    );
    assert!(
        commands["mesh-adaptive"]
            .windows(2)
            .any(|p| p == ["--adaptive-generation-min-concurrency", "1"])
    );
    assert!(
        !commands["mesh"]
            .iter()
            .any(|v| v == "--adaptive-generation-concurrency")
    );
    root.close().unwrap();
}

