fn optional_matrix_requires_linux_cuda_and_preserves_required_refusal() {
    let root = tempfile::tempdir().unwrap();
    let mut config: Value = serde_json::from_slice(include_bytes!(concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/../../evals/skippy-competitive-benchmark.json"
    )))
    .unwrap();
    let artifact = json!({"path":root.path().join("inert"),"sha256":"a".repeat(64)});
    let backend = json!({"executable":artifact,"version_sha256":"b".repeat(64),"cwd":root.path(),"runtime":artifact,"tokenizer":artifact,"hf_config":null,"comparison_model":null,"match_kv_capacity":false});
    let mut input:Input=serde_json::from_value(json!({"config":root.path().join("config.json"),"config_sha256":"c".repeat(64),"platform":"cuda","models":[{"key":"llama32-dense","model":artifact,"backends":{"llama":backend,"mesh":backend,"vllm":backend,"sglang":backend}}],"workloads":["synthetic"],"optional_arms":["vllm","sglang"],"required_comparisons":[],"adaptive":false,"manifest":null,"benchy":null,"output":root.path().join("output"),"timeout_seconds":120,"cell_timeout_seconds":20,"request_timeout_seconds":2,"resume":false,"force":false})).unwrap();
    for arm in ["vllm", "sglang"] {
        config["models"][0]["comparison_support"][arm] = json!({"available":true});
    }
    let bytes = serde_json::to_vec(&config).unwrap();
    let off = super::super::competitive_roster::select_on(&config, &bytes, &input, false).unwrap();
    assert!(
        off.cells
            .iter()
            .all(|cell| cell["arm"] == "llama" || cell["arm"] == "mesh")
    );
    assert!(
        off.availability["models"]
            .as_array()
            .unwrap()
            .iter()
            .all(|row| row["selected"] == false
                && row["reason"] == "optional engine requires Linux CUDA")
    );
    let on = super::super::competitive_roster::select_on(&config, &bytes, &input, true).unwrap();
    for arm in ["vllm", "sglang"] {
        assert!(on.cells.iter().any(|cell| cell["arm"] == arm));
    }
    input.required_comparisons = vec!["vllm".into(), "sglang".into()];
    assert!(super::super::competitive_roster::select_on(&config, &bytes, &input, false).is_err());
    input.models[0].backends.remove("sglang");
    assert!(super::super::competitive_roster::select_on(&config, &bytes, &input, true).is_err());
    input.required_comparisons = vec!["vllm".into()];
    let optional_missing =
        super::super::competitive_roster::select_on(&config, &bytes, &input, true).unwrap();
    assert!(
        !optional_missing
            .cells
            .iter()
            .any(|cell| cell["arm"] == "sglang")
    );
    assert!(
        optional_missing
            .cells
            .iter()
            .any(|cell| cell["arm"] == "vllm")
    );
    assert!(
        optional_missing
            .cells
            .iter()
            .any(|cell| cell["arm"] == "mesh")
    );
    assert!(
        optional_missing.availability["models"]
            .as_array()
            .unwrap()
            .iter()
            .any(|row| row["arm"] == "sglang"
                && row["selected"] == false
                && row["source_pinned_exclusion"] == false
                && row["reason"] == "no prepared backend supplied")
    );
    input.platform = "metal".into();
    assert!(super::super::competitive_roster::select_on(&config, &bytes, &input, true).is_err());
    root.close().unwrap();
}

fn fair_optional_capacity_uses_total_token_budget_and_pinned_native_override_without_gguf_flags() {
    let root = tempfile::tempdir().unwrap();
    let model_file = root.path().join("fixture.gguf");
    std::fs::write(&model_file, b"model").unwrap();
    let model_hash = crate::product::digest::file_sha256(&model_file)
        .unwrap_or_else(|failure| panic!("fixture digest: {}", failure.error));
    let binary = std::env::current_exe().unwrap();
    let binary_hash = crate::product::digest::file_sha256(&binary)
        .unwrap_or_else(|failure| panic!("fixture digest: {}", failure.error));
    let tokenizer = root.path().join("tokenizer");
    std::fs::create_dir(&tokenizer).unwrap();
    std::fs::write(tokenizer.join("tokenizer.json"), b"{}").unwrap();
    let config_target = tokenizer.join("config.json");
    std::fs::write(&config_target, b"{\"model_type\":\"fixture\"}").unwrap();
    let config_hash = crate::product::digest::file_sha256(&config_target)
        .unwrap_or_else(|failure| panic!("fixture digest: {}", failure.error));
    let config_directory = root.path().join("vllm-config");
    std::fs::create_dir(&config_directory).unwrap();
    let config_path = config_directory.join("config.json");
    #[cfg(unix)]
    std::os::unix::fs::symlink(&config_target, &config_path).unwrap();
    #[cfg(not(unix))]
    std::fs::copy(&config_target, &config_path).unwrap();
    let hash = crate::product::digest::tree_sha256(&tokenizer)
        .unwrap_or_else(|failure| panic!("fixture digest: {}", failure.error));

    let model = json!({"key":"fixture","model_id":"fixture:model","sha256":model_hash,"tokenizer_sha256":hash,"vllm_hf_config":{"sha256":config_hash},"comparison_inputs":{"vllm":{"sha256":hash,"tensor_equivalence_sha256":"a".repeat(64)}},"vllm_capacity":{"reference_tokens":131072,"reference_blocks":2560}});
    let backend:Backend=serde_json::from_value(json!({"executable":{"path":binary,"sha256":binary_hash},"version_sha256":"b".repeat(64),"cwd":root.path(),"runtime":null,"tokenizer":{"path":tokenizer,"sha256":hash},"hf_config":{"path":config_path,"sha256":config_hash},"comparison_model":{"path":tokenizer,"sha256":hash},"match_kv_capacity":true})).unwrap();
    let artifact = Artifact {
        path: model_file,
        sha256: model_hash,
    };
    let cell = json!({"arm":"vllm"});
    let mut provenance = json!({});
    let selection = Selection {
        model: &model,
        cell: &cell,
        backend: &backend,
        artifact: &artifact,
        port: 1234,
        directory: root.path(),
        capacity: Capacity {
            context: 65536,
            lanes: 16,
        },
        cache: true,
    };
    let command = external(&selection, "vllm", "fixture:model", &mut provenance).unwrap();
    assert!(
        command
            .windows(2)
            .any(|pair| pair == ["--max-model-len", "65536"])
    );
    assert!(
        command
            .windows(2)
            .any(|pair| pair == ["--max-num-seqs", "16"])
    );
    assert!(
        command
            .windows(2)
            .any(|pair| pair == ["--num-gpu-blocks-override", "1280"])
    );
    assert!(
        command
            .windows(2)
            .any(|pair| pair[0] == "--hf-config-path"
                && pair[1] == config_directory.to_str().unwrap())
    );
    assert_ne!(hash, config_hash);
    std::fs::write(config_path.canonicalize().unwrap(), b"changed").unwrap();
    assert!(hf_config_directory(backend.hf_config.as_ref().unwrap()).is_err());
    assert!(!command.contains(&"--load-format".into()));
    assert!(!command.contains(&"--quantization".into()));
    assert_eq!(provenance["comparison_input_sha256"], hash);
    assert_eq!(provenance["tensor_equivalence_sha256"], "a".repeat(64));
    assert_eq!(
        capacity_args(&json!({}), "sglang", 131072, true).unwrap(),
        ["--max-total-tokens", "131072"]
    );
    root.close().unwrap();
}

